===GLOBALS_CSS===
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&display=swap');

.milibank-portal {
  --portal-bg: #f5f7fa;
  --primary: #2a5ca8;
  --text-main: #111827;
  --text-sub: #6b7280;
  --text-caption: #9ca3af;
  --border-color: #e5e7eb;
  font-family: 'Noto Sans JP', sans-serif;
  min-height: 100vh;
  background: var(--portal-bg);
  color: var(--text-main);
}

.milibank-portal * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.milibank-portal a {
  color: inherit;
  text-decoration: none;
}

.milibank-portal ul,
.milibank-portal ol {
  list-style: none;
}

.milibank-portal img {
  max-width: 100%;
  display: block;
}

.milibank-portal button {
  font-family: inherit;
  cursor: pointer;
}

.milibank-portal input,
.milibank-portal textarea,
.milibank-portal select {
  font-family: inherit;
}
===END===

